Target: ${spec.name}${attemptLabel}
Objective: ${spec.objective}
Candidate file, absolute path: ${candidatePath}

Hard rules:
- Edit only the candidate file above. Do not modify repository source, docs, package files, tests, or git state.
- Export either \`activate(letta)\` or a default function.
- Use the trusted local mod API directly; do not import from "@/..." or from this repo's src files.
- Prefer a small implementation that satisfies the behavior over a polished product mod.
- If you register an eval-facing tool, set \`requiresApproval: false\` and keep it read-only.
- Do not run tests or lint. Write the candidate file and stop.
${diversitySection}${historySection}
Mod API surface guide:
- Use \`turn_start\` for policy/guidance that should influence model planning.
- Use \`tool_start\` for tool argument inspection, normalization, rewrites, or blocking-adjacent behavior before execution.
- Register a tool only when the agent needs a new callable capability or observable state.
- Pick the narrowest surface that directly satisfies the env; a reminder alone is not enough when the env asks for tool-boundary behavior.

Minimal mod API reminder:
\`\`\`ts
export function activate(letta) {
  const disposers = [];
  if (letta.capabilities.events.tools) {
    disposers.push(letta.events.on("tool_start", (event) => {
      // Use this for command/argument rewrites before tool execution.
      if (event.toolName === "exec_command" && typeof event.args.cmd === "string") {
        const rewritten = event.args.cmd.replace("old command", "new command");
        if (rewritten !== event.args.cmd) {
          return { args: { ...event.args, cmd: rewritten } };
        }
      }
    }));
  }
  if (letta.capabilities.events.turns) {
    disposers.push(letta.events.on("turn_start", (event) => {
      // event.input is an array of message/approval objects. Do not append
      // strings to existing content because content may be structured parts.
      event.input = [
        ...event.input,
        { type: "message", role: "system", content: "mod reminder" },
      ];
      return { input: event.input };
    }));
  }
  if (letta.capabilities.tools) {
    disposers.push(letta.tools.register({
      name: "example_tool",
      description: "Short tool description",
      parameters: { type: "object", properties: {}, additionalProperties: false },
      requiresApproval: false,
      parallelSafe: true,
      run(ctx) {
        // For conversation-scoped state, use ctx.conversation.id or
        // ctx.sessionId as the key.
        return "ok";
      },
    }));
  }
  return () => disposers.reverse().forEach((dispose) => dispose());
}
