    61	export function selectDefaultAgentModel(params: {
    62	  preferredModel?: string;
    63	  isSelfHosted: boolean;
    64	  availableHandles?: Iterable<string>;
    65	}): string | undefined {
    66	  const { preferredModel, isSelfHosted, availableHandles } = params;
    67	  const resolvedPreferred =
    68	    typeof preferredModel === "string" && preferredModel.length > 0
    69	      ? (resolveModel(preferredModel) ?? preferredModel)
    70	      : undefined;
    71	
    72	  if (!isSelfHosted) {
    73	    return resolvedPreferred;
    74	  }
    75	
    76	  const handles = availableHandles ? new Set(availableHandles) : null;
    77	  if (!handles) {
    78	    return resolvedPreferred;
    79	  }
    80	
    81	  if (resolvedPreferred && handles.has(resolvedPreferred)) {
    82	    return resolvedPreferred;
    83	  }
    84	
    85	  const firstNonAutoHandle = Array.from(handles).find(
    86	    (handle) => handle !== "letta/auto" && handle !== "letta/auto-fast",
    87	  );
    88	  if (firstNonAutoHandle) {
    89	    return firstNonAutoHandle;
    90	  }
    91	
    92	  const defaultHandle = getDefaultModel();
    93	  if (handles.has(defaultHandle)) {
    94	    return defaultHandle;
    95	  }
    96	
    97	  return Array.from(handles)[0];
    98	}
