   100	async function resolveDefaultAgentModel(
   101	  backend: Backend,
   102	  preferredModel?: string,
   103	): Promise<string | undefined> {
   104	  if (!isSelfHostedServer()) {
   105	    return selectDefaultAgentModel({
   106	      preferredModel,
   107	      isSelfHosted: false,
   108	    });
   109	  }
   110	
   111	  try {
   112	    const availableHandles = new Set(
   113	      (await backend.listModels())
   114	        .map((model) => model.handle)
   115	        .filter((handle): handle is string => typeof handle === "string"),
   116	    );
   117	
   118	    return selectDefaultAgentModel({
   119	      preferredModel,
   120	      isSelfHosted: true,
   121	      availableHandles,
   122	    });
   123	  } catch {
   124	    return selectDefaultAgentModel({
   125	      preferredModel,
   126	      isSelfHosted: true,
   127	    });
   128	  }
   129	}
