 17	/**
 18	 * Evaluate reflection triggers at turn end and launch the reflection subagent
 19	 * if one fires. Call after the turn's transcript delta has been appended so
 20	 * step counts include the just-finished turn.
 21	 */
 22	export async function maybeLaunchPostTurnReflection(params: {
 23	  agentId?: string | null;
 24	  conversationId: string;
 25	  memfsEnabled: boolean;
 26	  reflectionSettings: ReflectionSettings;
 27	  reminderState: SharedReminderState;
 28	  contextTracker: ContextTracker;
 29	  launch: PostTurnReflectionLauncher;
 30	  onCompaction?: () => Promise<void>;
 31	  getTranscriptState?: typeof getReflectionTranscriptState;
 32	}): Promise<boolean> {
 33	  if (!params.agentId || !params.memfsEnabled) {
 34	    return false;
 35	  }
 36	
 37	  syncReminderStateFromContextTracker(
 38	    params.reminderState,
 39	    params.contextTracker,
 40	  );
 41	  const hadCompactionEvent = params.reminderState.pendingReflectionTrigger;
 42	  if (hadCompactionEvent) {
 43	    await params.onCompaction?.();
 44	  }
 45	
 46	  switch (params.reflectionSettings.trigger) {
 47	    case "off":
 48	      params.reminderState.pendingReflectionTrigger = false;
 49	      return false;
 50	    case "compaction-event": {
 51	      if (!params.reminderState.pendingReflectionTrigger) {
 52	        return false;
 53	      }
 54	      params.reminderState.pendingReflectionTrigger = false;
 55	      return params.launch("compaction-event");
 56	    }
 57	    case "step-count": {
 58	      params.reminderState.pendingReflectionTrigger = false;
 59	      const readTranscriptState =
 60	        params.getTranscriptState ?? getReflectionTranscriptState;
 61	      const transcriptState = await readTranscriptState(
 62	        params.agentId,
 63	        params.conversationId,
 64	      );
 65	      if (
 66	        !shouldFireStepCountTrigger(
 67	          transcriptState.steps_since_last_successful_reflection,
 68	          params.reflectionSettings,
 69	        )
 70	      ) {
 71	        return false;
 72	      }
 73	      return params.launch("step-count");
 74	    }
 75	  }
 76	}
