283	export async function shouldRunQueuedReflectionLaunch(
284	  options: ReflectionLaunchOptions,
285	  deps: {
286	    getTranscriptState?: typeof getReflectionTranscriptState;
287	    getSettings?: typeof getReflectionSettings;
288	  } = {},
289	): Promise<boolean> {
290	  if (options.triggerSource !== "step-count") {
291	    return true;
292	  }
293	
294	  const settings =
295	    options.reflectionSettings ??
296	    (deps.getSettings ?? getReflectionSettings)(options.agentId);
297	  const readTranscriptState =
298	    deps.getTranscriptState ?? getReflectionTranscriptState;
299	  const transcriptState = await readTranscriptState(
300	    options.agentId,
301	    options.conversationId,
302	  );
303	  const shouldLaunch = shouldFireStepCountTrigger(
304	    transcriptState.steps_since_last_successful_reflection,
305	    settings,
306	  );
307	
308	  if (!shouldLaunch) {
309	    debugLog(
310	      "memory",
311	      `Skipping queued reflection launch (${options.triggerSource}) because the trigger threshold is no longer met`,
312	    );
313	  }
314	
315	  return shouldLaunch;
316	}
