318	function schedulePendingReflectionLaunch(agentId: string): void {
319	  const pendingOptions = pendingReflectionLaunches.get(agentId);
320	  if (!pendingOptions) return;
321	  pendingReflectionLaunches.delete(agentId);
322	
323	  queueMicrotask(() => {
324	    void (async () => {
325	      if (!(await shouldRunQueuedReflectionLaunch(pendingOptions))) {
326	        return;
327	      }
328	      await launchReflectionSubagent(pendingOptions);
329	    })().catch((error) => {
330	      debugWarn(
331	        "memory",
332	        `Failed to launch queued reflection (${pendingOptions.triggerSource}): ${
333	          error instanceof Error ? error.message : String(error)
334	        }`,
335	      );
336	    });
337	  });
338	}
