350	function getReflectionCompletionMessage(
351	  integration: ReflectionMemoryWorktreeFinalizeResult,
352	): MemorySubagentSuccessMessageOverride | undefined {
353	  switch (integration.status) {
354	    case "merged":
355	      return undefined;
356	    case "no_changes":
357	      return ({ action }) =>
358	        `${action}; no durable memory changes were needed.`;
359	    case "parent_dirty":
360	      return "Tried to reflect, but parent memory had uncommitted changes; will retry later.";
361	    case "merge_conflict":
362	      return "Tried to reflect, but memory updates conflicted with newer changes; will retry later.";
363	    case "dirty_uncommitted":
364	      return "Tried to reflect, but memory changes were not committed cleanly; will retry later.";
365	    case "failed":
366	      return integration.failurePhase === "integration"
367	        ? `${integration.summary} Will retry later.`
368	        : "Tried to reflect, but memory updates were not completed cleanly; will retry later.";
369	  }
370	}
