 12	const GIT_TIMEOUT_MS = 30_000;
 13	const HARNESS_GIT_ENV = {
 14	  GIT_AUTHOR_NAME: "Letta Code",
 15	  GIT_AUTHOR_EMAIL: "noreply@letta.com",
 16	  GIT_COMMITTER_NAME: "Letta Code",
