 20	interface GitResult {
 21	  stdout: string;
 22	  stderr: string;
 23	}
 24	
 25	async function runGit(cwd: string, args: string[]): Promise<GitResult> {
 26	  try {
 27	    const allArgs = [...GIT_DISABLE_COMMIT_SIGNING_ARGS, ...args];
 28	    const { stdout, stderr } = await execFile("git", allArgs, {
 29	      cwd,
 30	      env: {
 31	        ...process.env,
 32	        ...HARNESS_GIT_ENV,
 33	      },
 34	      encoding: "utf-8",
 35	      timeout: GIT_TIMEOUT_MS,
 36	      maxBuffer: 1024 * 1024 * 5,
 37	    });
 38	    return {
 39	      stdout: stdout?.toString() ?? "",
 40	      stderr: stderr?.toString() ?? "",
 41	    };
 42	  } catch (error) {
 43	    const err = error as Error & {
 44	      stdout?: string;
 45	      stderr?: string;
 46	      code?: string | number;
 47	    };
 48	    const details = [err.message, err.stderr, err.stdout]
 49	      .filter((part): part is string => Boolean(part?.trim()))
 50	      .join("\n");
 51	    throw new Error(
 52	      `git ${args.join(" ")} failed in ${cwd}${details ? `: ${details}` : ""}`,
 53	    );
 54	  }
 55	}
 56	
 57	async function tryRunGit(
 58	  cwd: string,
 59	  args: string[],
 60	): Promise<GitResult | null> {
 61	  try {
 62	    return await runGit(cwd, args);
 63	  } catch {
 64	    return null;
 65	  }
 66	}
