 68	function normalizeGitPath(path: string, cwd: string): string {
 69	  const trimmed = path.trim();
 70	  if (!trimmed) return trimmed;
 71	  return isAbsolute(trimmed) ? trimmed : resolve(cwd, trimmed);
 72	}
