 74	function buildReflectionWorktreeId(now: Date = new Date()): string {
 75	  const timestamp = now
 76	    .toISOString()
 77	    .replace(/[^0-9]/g, "")
 78	    .slice(0, 14);
 79	  return `${timestamp}-${randomUUID().slice(0, 8)}`;
 80	}
