 82	function summarizeReflectionCommitSubject(subject: string): string {
 83	  const summary = subject
 84	    .trim()
 85	    .replace(/^[a-z]+(?:\([^)]+\))?!?:\s*/i, "")
 86	    .trim();
 87	  return summary || "reflection memory updates";
 88	}
