 90	async function buildReflectionMergeMessage(
 91	  parentMemoryDir: string,
 92	  branchName: string,
 93	): Promise<string> {
 94	  const result = await tryRunGit(parentMemoryDir, [
 95	    "log",
 96	    "-1",
 97	    "--pretty=%s",
