104	export interface ReflectionMemoryWorktree {
105	  id: string;
106	  parentMemoryDir: string;
107	  worktreeBaseDir: string;
108	  worktreeDir: string;
109	  branchName: string;
110	  baseHead: string;
111	  gitCommonDir: string;
112	}
