119	export async function createReflectionMemoryWorktree(
120	  options: CreateReflectionMemoryWorktreeOptions,
121	): Promise<ReflectionMemoryWorktree> {
122	  const parentMemoryDir = resolve(options.parentMemoryDir);
123	  const id = buildReflectionWorktreeId(options.now);
124	  const worktreeBaseDir = join(dirname(parentMemoryDir), "memory-worktrees");
125	  const worktreeDir = join(worktreeBaseDir, `reflection-${id}`);
126	  const branchName = `letta/reflection/${id}`;
127	
128	  await mkdir(worktreeBaseDir, { recursive: true });
129	
130	  const { stdout: baseHeadOut } = await runGit(parentMemoryDir, [
131	    "rev-parse",
132	    "--verify",
133	    "HEAD",
134	  ]);
135	  const baseHead = baseHeadOut.trim();
136	  if (!baseHead) {
137	    throw new Error(
138	      `Unable to create reflection memory worktree: ${parentMemoryDir} has no HEAD`,
139	    );
140	  }
141	
142	  await runGit(parentMemoryDir, [
143	    "worktree",
144	    "add",
145	    worktreeDir,
146	    "-b",
147	    branchName,
148	    baseHead,
149	  ]);
150	
151	  const { stdout: commonDirOut } = await runGit(worktreeDir, [
152	    "rev-parse",
153	    "--git-common-dir",
154	  ]);
155	  const gitCommonDir = normalizeGitPath(commonDirOut, worktreeDir);
156	  debugLog(
157	    "memfs-git",
158	    "reflection worktree created id=%s branch=%s dir=%s parent=%s baseHead=%s gitCommonDir=%s",
159	    id,
160	    branchName,
161	    worktreeDir,
162	    parentMemoryDir,
163	    baseHead,
164	    gitCommonDir,
165	  );
166	
167	  return {
168	    id,
169	    parentMemoryDir,
170	    worktreeBaseDir,
171	    worktreeDir,
172	    branchName,
173	    baseHead,
174	    gitCommonDir,
175	  };
176	}
