284	async function cleanupWorktreeAndBranch(
285	  parentMemoryDir: string,
286	  worktreeDir: string,
287	  branchName: string,
288	  options: { force?: boolean } = {},
289	): Promise<void> {
290	  const removedWorktree = existsSync(worktreeDir);
291	  if (removedWorktree) {
