    99	): string | null {
   100	  const env = options.env ?? process.env;
   101	  const homeDir = options.homeDir ?? env.HOME ?? env.USERPROFILE ?? homedir();
   102	
   103	  const explicitAgentId = options.agentId?.trim();
   104	  if (explicitAgentId) {
   105	    return getScopedMemoryFilesystemRoot(explicitAgentId, { env, homeDir });
