   184	  if (!(await isLettaCloud())) return body;
   185	
   186	  const { GIT_MEMORY_ENABLED_TAG } = await import("@/agent/agent-tags");
   187	  return stampMemfsTagOnCreateBody(body, GIT_MEMORY_ENABLED_TAG);
