1311	
1312	  const status = line.slice(0, 2);
1313	  if (status === " D" || status === "D " || status === "DD") {
1314	    return null;
1315	  }
1316	
1317	  const rawPath = line.slice(3);
1318	  const renameSeparator = " -> ";
1319	  const path = rawPath.includes(renameSeparator)
1320	    ? (rawPath.split(renameSeparator).pop() ?? rawPath)
1321	    : rawPath;
1322	
1323	  return path.replace(/^"|"$/g, "");
1324	}
