1888	async function getMemoryConflictSummary(
1889	  memoryDir: string,
1890	  statusOut?: string,
1891	): Promise<string | null> {
1892	  let operation: string | null = null;
1893	  try {
1894	    const gitDir = await getMemoryGitDir(memoryDir);
1895	    if (existsSync(join(gitDir, "MERGE_HEAD"))) {
1896	      operation = "merge in progress";
1897	    } else if (
1898	      existsSync(join(gitDir, "rebase-merge")) ||
1899	      existsSync(join(gitDir, "rebase-apply"))
1900	    ) {
1901	      operation = "rebase in progress";
1902	    }
1903	  } catch {
1904	    operation = null;
1905	  }
1906	
1907	  const status =
1908	    statusOut ?? (await runGit(memoryDir, ["status", "--porcelain"])).stdout;
1909	  const conflictedFiles = status
1910	    .split("\n")
1911	    .map((line) => line.trimEnd())
1912	    .filter((line) => line && isUnmergedStatusCode(line.slice(0, 2)))
1913	    .map((line) => line.slice(3).trim())
1914	    .filter(Boolean);
1915	
1916	  if (!operation && conflictedFiles.length === 0) {
1917	    return null;
1918	  }
1919	
1920	  const parts: string[] = [];
1921	  if (operation) {
1922	    parts.push(operation);
1923	  }
1924	  if (conflictedFiles.length > 0) {
1925	    parts.push(
1926	      `conflicted file(s): ${conflictedFiles.slice(0, 10).join(", ")}${
1927	        conflictedFiles.length > 10
1928	          ? `, and ${conflictedFiles.length - 10} more`
1929	          : ""
1930	      }`,
1931	    );
1932	  }
1933	  return parts.join("; ");
1934	}
